CREATE TABLE `academy_profiles` (`academy_id` text PRIMARY KEY NOT NULL,`legal_name` text NOT NULL,`display_name` text NOT NULL,`description` text NOT NULL,`address_line_1` text NOT NULL,`address_line_2` text,`city` text NOT NULL,`region` text NOT NULL,`postal_code` text NOT NULL,`country_code` text DEFAULT 'US' NOT NULL,`latitude` text,`longitude` text,`phone` text,`website` text,`hours_json` text DEFAULT '{}' NOT NULL,`claim_status` text DEFAULT 'draft' NOT NULL,`public_status` text DEFAULT 'private' NOT NULL,`updated_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `academy_staff_profiles` (`id` text PRIMARY KEY NOT NULL,`academy_id` text NOT NULL,`display_name` text NOT NULL,`title` text NOT NULL,`email` text,`phone` text,`bio` text,`is_primary_contact` integer DEFAULT false NOT NULL,`public_contact` integer DEFAULT false NOT NULL,`status` text DEFAULT 'active' NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `user_profiles` (`user_email` text PRIMARY KEY NOT NULL,`display_name` text NOT NULL,`home_academy_id` text,`birth_year` integer,`belt` text,`location_text` text,`goals` text,`concerns` text,`strengths` text,`weaknesses` text,`opportunities` text,`visibility` text DEFAULT 'private' NOT NULL,`booking_enabled` integer DEFAULT false NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `academy_reviews` (`id` text PRIMARY KEY NOT NULL,`academy_id` text NOT NULL,`author_email` text NOT NULL,`rating` integer NOT NULL,`title` text NOT NULL,`body` text NOT NULL,`visit_type` text NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`academy_response` text,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `academy_connections` (`id` text PRIMARY KEY NOT NULL,`requester_academy_id` text,`requester_email` text NOT NULL,`target_academy_id` text NOT NULL,`connection_type` text NOT NULL,`message` text,`status` text DEFAULT 'requested' NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `training_bookings` (`id` text PRIMARY KEY NOT NULL,`academy_id` text NOT NULL,`athlete_email` text NOT NULL,`offering_type` text NOT NULL,`start_at` integer NOT NULL,`duration_minutes` integer NOT NULL,`party_size` integer DEFAULT 1 NOT NULL,`message` text,`status` text DEFAULT 'requested' NOT NULL,`price_cents` integer,`currency` text DEFAULT 'usd' NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `referral_attributions` (`id` text PRIMARY KEY NOT NULL,`academy_id` text NOT NULL,`referred_user_email` text NOT NULL,`code` text NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`qualified_at` integer,`created_at` integer NOT NULL);
CREATE TABLE `revenue_share_ledger` (`id` text PRIMARY KEY NOT NULL,`academy_id` text NOT NULL,`attribution_id` text,`provider_invoice_id` text,`gross_cents` integer NOT NULL,`eligible_net_cents` integer NOT NULL,`share_basis_points` integer DEFAULT 1000 NOT NULL,`share_cents` integer NOT NULL,`entry_type` text NOT NULL,`status` text DEFAULT 'pending' NOT NULL,`available_at` integer,`paid_at` integer,`created_at` integer NOT NULL);
CREATE UNIQUE INDEX `referral_code_unique` ON `referral_attributions` (`code`);
CREATE INDEX `academy_profiles_location_idx` ON `academy_profiles` (`region`,`city`,`public_status`);
CREATE INDEX `bookings_academy_start_idx` ON `training_bookings` (`academy_id`,`start_at`);
CREATE INDEX `revenue_share_academy_status_idx` ON `revenue_share_ledger` (`academy_id`,`status`);
